import { load, dump, JSON_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('resolves signed hex/octal/binary !!int tags in the JSON schema', () => {
    assert.strictEqual(load('!!int "-0x1F"', { schema: JSON_SCHEMA }), -31);
    assert.strictEqual(load('!!int "+0x10"', { schema: JSON_SCHEMA }), 16);
    assert.strictEqual(load('!!int "-0b101"', { schema: JSON_SCHEMA }), -5);
    assert.strictEqual(load('!!int "-0o17"', { schema: JSON_SCHEMA }), -15);
    // sanity: signed decimal is unchanged
    assert.strictEqual(load('!!int "-123"', { schema: JSON_SCHEMA }), -123);
  });
});
"}, "note": "The change removes sign handling from the JSON-schema integer parser, so explicit `!!int` tags with signed binary/octal/hex values now fall through to `parseInt(value, 10)`, which stops at the `0x`/`0b`/`0o` prefix and returns 0/-0 instead of the correct number (e.g. `!!int "-0x1F"` yields -0 rather than -31). Implicit plain scalars are unaffected, which is why the existing suite stays green."}
